import{_ as e,o,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"歷史記錄","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/settings/history.md","filePath":"zh-TW/user-guide/settings/history.md","lastUpdated":1786537234000}'),s={name:"zh-TW/user-guide/settings/history.md"};function n(i,t,l,d,c,h){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="歷史記錄" tabindex="-1">歷史記錄 <a class="header-anchor" href="#歷史記錄" aria-label="Permalink to &quot;歷史記錄&quot;">​</a></h1><p>兩個分頁，各自獨立:<strong>搜尋記錄</strong>和<strong>關鍵字記錄</strong>。</p><h2 id="搜尋記錄" tabindex="-1">搜尋記錄 <a class="header-anchor" href="#搜尋記錄" aria-label="Permalink to &quot;搜尋記錄&quot;">​</a></h2><p>記錄你實際開啟過的結果，以便下次搜尋類似內容時能優先展示。</p><p>搜尋記錄會同時記住開啟的路徑和當時使用的查詢。之後輸入與該查詢模糊比對的文字時，快速視窗、內嵌視窗和完整視窗都能重新叫回仍然存在的路徑並優先顯示；例如用 <code>bcomp</code> 開啟 <code>BCompare.exe</code> 後，搜尋 <code>bc</code> 也能讓它回到前列。內嵌搜尋會把目前資料夾範圍內的符合項目放進<strong>目前資料夾</strong>，其餘放進<strong>全域搜尋</strong>；不存在的路徑會被忽略，同一路徑只會顯示一次。</p><ul><li><strong>啟用歷史記錄</strong> 核取方塊 —— 開啟/關閉記錄功能;關閉後既有的記錄會保留，只是不再新增。</li><li><strong>搜尋框</strong> —— 按關鍵字篩選目前顯示的歷史清單。</li><li>每條記錄都可以單獨刪除，也可以用<strong>清空全部記錄</strong>一次性清空。</li></ul><h2 id="關鍵字記錄" tabindex="-1">關鍵字記錄 <a class="header-anchor" href="#關鍵字記錄" aria-label="Permalink to &quot;關鍵字記錄&quot;">​</a></h2><p>記錄你在快速視窗搜尋框裡實際輸入過的原始文字(而不是開啟了什麼)，方便用<a href="./../hotkeys.html#全域熱鍵">關鍵字歷史熱鍵</a>(預設 <code>Alt+Up</code> / <code>Alt+Down</code>)翻閱最近的查詢。</p><ul><li>同樣有<strong>啟用歷史記錄</strong>開關、搜尋篩選、單條刪除和<strong>清空全部記錄</strong>按鈕，只是作用對象是關鍵字而不是開啟過的結果。</li></ul>',9)])])}const u=e(s,[["render",n]]);export{p as __pageData,u as default};
